import streamlit as stimport pandas as pdimport yamlfrom pathlib import Pathfrom src.io_utils import load_table, previewfrom src.mapper import suggest_mapping_fuzzy, suggest_mapping_llmfrom src.rules import eval_checkfrom src.llm import explain_specimenfrom src.report import make_pdfdef parse_generated_yaml(yaml_text: str) -> dict:    """    Robustly parse YAML from LLM, handling markdown fences and wrapper keys.    """    import re        # 1) Strip ```yaml fences if present    yt = yaml_text.strip()    fence_match = re.search(r"```(?:yaml)?\s*([\s\S]*?)```", yt, flags=re.IGNORECASE)    if fence_match:        yt = fence_match.group(1).strip()    # 2) Load YAML    tmpl = yaml.safe_load(yt)    if not isinstance(tmpl, dict):        raise ValueError("YAML must be a mapping at the top level.")    # 3) Unwrap if model returned a wrapper like 'compliance_rules:'    if "compliance_rules" in tmpl and isinstance(tmpl["compliance_rules"], dict):        tmpl = tmpl["compliance_rules"]    # 4) Minimal normalization / required fields    tmpl.setdefault("standard_id", "GENERATED")    tmpl.setdefault("version", "1.0")    tmpl.setdefault("units", {})        # Ensure units are strings    if "units" in tmpl and isinstance(tmpl["units"], dict):        for k, v in tmpl["units"].items():            tmpl["units"][k] = str(v)        checks = tmpl.get("checks", [])    if not isinstance(checks, list) or not checks:        raise ValueError("No checks[] found.")        # Validate and coerce checks    for c in checks:        if "unit" in c:            c["unit"] = str(c["unit"])        if "op" not in c or "metric" not in c:            raise ValueError("Each check must include metric and op.")        # Ensure numeric values are properly typed        if "value" in c:            try:                c["value"] = float(c["value"]) if isinstance(c["value"], str) and c["value"].replace('.','').replace('-','').isdigit() else c["value"]            except:                pass        if "min" in c:            try:                c["min"] = float(c["min"]) if isinstance(c["min"], str) and c["min"].replace('.','').replace('-','').isdigit() else c["min"]            except:                pass        if "max" in c:            try:                c["max"] = float(c["max"]) if isinstance(c["max"], str) and c["max"].replace('.','').replace('-','').isdigit() else c["max"]            except:                pass        tmpl["checks"] = checks    return tmpldef propose_units_llm(df, mapping, required_metrics, tpl_units):    """    Ask an LLM to infer units for each required metric using header text and a few sample values.    Falls back to template defaults if LLM is unavailable or fails.    """    import os, requests, json    key = os.environ.get("OPENAI_API_KEY")    model = os.environ.get("OPENAI_MODEL", "gpt-4o-mini")    # Build a tiny sample payload for the LLM    sample = {}    for m, h in mapping.items():        if h and m in required_metrics and h in df.columns:            vals = df[h].dropna().astype(str).tolist()[:5]            sample[m] = {"header": h, "values": vals}    # Fallback: just return template units if no API key    if not key:        return {m: tpl_units.get(m, "") for m in required_metrics}    system = "Infer measurement units for each metric from header names and sample numeric values. Prefer SI (MPa, GPa, %, mm/min). Return JSON only."    user = f"Template default units: {tpl_units}\nSamples: {sample}\nReturn JSON: {{\"units\": {{metric: unit_string}}}}."    try:        r = requests.post(            "https://api.openai.com/v1/chat/completions",            headers={"Authorization": f"Bearer {key}", "Content-Type": "application/json"},            json={                "model": model,                "messages": [{"role": "system", "content": system}, {"role": "user", "content": user}],                "temperature": 0.1,                "max_tokens": 200,            },            timeout=60,        )        if r.status_code != 200:            # Rate limit or other failure → fallback to template units            return {m: tpl_units.get(m, "") for m in required_metrics}        txt = r.json()["choices"][0]["message"]["content"]        units = {}        try:            units = json.loads(txt).get("units", {})        except Exception:            units = {}        # Ensure every required metric has something        for m in required_metrics:            if not units.get(m):                units[m] = tpl_units.get(m, "")        return units    except Exception:        return {m: tpl_units.get(m, "") for m in required_metrics}from typing import List, Dictdef _load_playbook():    p = Path("templates/remediation_playbook.yaml")    if p.exists():        with open(p, "r") as f:            return yaml.safe_load(f) or {}    return {"rules": []}PLAYBOOK = _load_playbook()def _extract_failing_metrics(rationale: str) -> List[str]:    """    Parse the 'rationale' string (joined by '; ') and return metric names that failed/missing/error.    We expect segments like: 'tensile_strength >= ... | measured=... | margin=...'    We'll mark a metric as 'failing' if the segment contains 'FAIL', 'MISSING', or 'ERROR'.    """    fails = []    if not rationale:        return fails    for seg in rationale.split(";"):        seg_low = seg.strip().lower()        # first token before space should be the metric (we formatted it that way in rules.py)        metric = seg.strip().split()[0] if seg.strip() else ""        if metric and any(key in seg_low for key in ["fail", "missing", "error"]):            fails.append(metric)    return list(dict.fromkeys(fails))  # de-dup, keep orderdef enrich_with_playbook(specimen_row: pd.Series, base_text: str) -> str:    failing = _extract_failing_metrics(specimen_row.get("rationale", ""))    if not failing or not PLAYBOOK.get("rules"):        return base_text    tips: List[str] = []    for rule in PLAYBOOK["rules"]:        m = rule.get("when_metric")        if not m:            continue        # basic match: if the metric shows up in failing list, apply        if any(m == fm or m in fm for fm in failing):            tips.extend(rule.get("suggestions", []))    if tips:        # keep it tight: up to 2 tips        tips = tips[:2]        base_text = base_text.rstrip() + "\n\n**Additional tips:**\n- " + "\n- ".join(tips)    return base_textst.set_page_config(page_title="VERA — AI Compliance Co-Pilot", layout="wide")st.title("VERA - AI Compliance Co-Pilot")st.caption("Validation & Explanation for Regulatory Assurance")# --- Sidebar: template loader ---st.sidebar.header("Template")# Filter out the playbook file from template dropdowntemplate_files = [p for p in Path("templates").glob("*.yaml") if p.name != "remediation_playbook.yaml"]template_names = [p.name for p in template_files]if not template_names:    st.warning("No templates found. Add YAML files to /templates.")    st.stop()# Only show template dropdown if we're using file templateif "template_override" not in st.session_state:    st.session_state.template_override = Noneif not st.session_state.template_override:    tpl_choice = st.sidebar.selectbox("Choose a template", template_names, index=0)    tpl_path = Path("templates") / tpl_choice    with open(tpl_path, "r") as f:        file_template = yaml.safe_load(f)else:    # When override is active, we don't need to load file template    file_template = {}  # placeholder    tpl_choice = "N/A (using generated template)"# Use override if available, otherwise use file templatetemplate = st.session_state.template_override or file_templaterequired_metrics = [c["metric"] for c in template.get("checks", [])]required_meta = template.get("metadata_required", [])std_id = template.get("standard_id", "STD")std_ver = template.get("version", "1.0")tpl_units = template.get("units", {})# Show which template is active - FIXED LOGICif st.session_state.template_override:    st.sidebar.success(f"Using in-memory template: **{std_id} v{std_ver}** (generated)")    if st.sidebar.button("⬅️ Revert to file template"):        st.session_state.template_override = None        st.rerun()else:    st.sidebar.caption(f"Using file template: {tpl_choice}")st.sidebar.write("**Required metrics:**", ", ".join(required_metrics))if required_meta:    st.sidebar.write("**Required metadata:**", ", ".join(required_meta))    # --- Sidebar: Generate template from natural language ---with st.sidebar.expander("🧠 Generate a template from natural language"):    nl = st.text_area(        "Describe your rule (e.g., 'tensile strength ≥ 55 MPa; elongation at break ≥ 8%')",        placeholder="tensile strength ≥ 55 MPa; elongation at break ≥ 8%; modulus between 1.5 and 3.5 GPa",        height=90    )    if st.button("Generate YAML template"):        import os, requests        key = os.environ.get("OPENAI_API_KEY")        model = os.environ.get("OPENAI_MODEL", "gpt-4o-mini")        if not key:            st.error("No OPENAI_API_KEY set. Add one to use this feature.")        else:            system = (                "Convert compliance rules into a compact YAML template for a validator. "                "Use metric names: tensile_strength, elongation_at_break, modulus, etc. "                "Include: standard_id, version, units (MPa, %, GPa default OK), checks[]. "                "Return YAML only—no commentary."            )            user = (                f"Rules (natural language): {nl}\n"                f"Preferred canonical metric names (if applicable): {required_metrics or ['tensile_strength','elongation_at_break','modulus']}\n"                "Example check formats:\n"                "- metric: tensile_strength\n  op: \">=\"\n  value: 55\n  unit: MPa\n"                "- metric: modulus\n  op: \"between\"\n  min: 1.5\n  max: 3.5\n  unit: GPa\n"            )            try:                r = requests.post(                    "https://api.openai.com/v1/chat/completions",                    headers={"Authorization": f"Bearer {key}", "Content-Type": "application/json"},                    json={                        "model": model,                        "messages": [{"role":"system","content":system},{"role":"user","content":user}],                        "temperature": 0.1,                        "max_tokens": 400                    },                    timeout=60                )                r.raise_for_status()                yaml_text = r.json()["choices"][0]["message"]["content"]                st.code(yaml_text, language="yaml")                # Buttons to adopt or clear                c1, c2 = st.columns(2)                with c1:                    if st.button("Use this template now"):                        try:                            tmpl = parse_generated_yaml(yaml_text)                            st.session_state.template_override = tmpl                            st.success("Template loaded in memory. It is now active.")                            st.rerun()                        except Exception as e:                            st.error(f"YAML parse/validation failed: {e}")                            # Show the problematic YAML for debugging                            st.code(yaml_text, language="yaml")                with c2:                    if st.button("Clear in-memory template"):                        st.session_state.template_override = None                        st.info("Reverted to file template.")                        st.rerun()            except requests.HTTPError as e:                if getattr(e.response, "status_code", None) == 429:                    st.warning("Rate limit: try again in a minute.")                else:                    st.error(f"API error: {e}")            except Exception as e:                st.error(f"Unexpected error: {e}")with st.sidebar.expander("Current template (YAML)"):    st.code(yaml.safe_dump(template, sort_keys=False), language="yaml")# Small toolbarcA, cB = st.columns([1,1])with cA:    if st.button("Reset session"):        # Clear all session state - ADD template_override to the list        keys_to_clear = ["df", "mapping", "units_map", "results_df", "explanations", "template_override", "last_filename"]        for k in keys_to_clear:            if k in st.session_state:                del st.session_state[k]        st.success("Session reset. Page will reload.")        st.rerun()with cB:    st.caption("Tip: Use sidebar to generate templates from natural language.")# --- Tabs ---tab1, tab2, tab3, tab4 = st.tabs(["1) Upload & Map", "2) Validate", "3) Explanations", "4) Export"])# session stateif "df" not in st.session_state: st.session_state.df = Noneif "mapping" not in st.session_state: st.session_state.mapping = {}if "units_map" not in st.session_state: st.session_state.units_map = {}if "results_df" not in st.session_state: st.session_state.results_df = Noneif "explanations" not in st.session_state: st.session_state.explanations = {}# ---------- Tab 1: Upload & Map ----------with tab1:    st.subheader("Upload results file (CSV/XLSX)")    up = st.file_uploader("Choose a file", type=["csv", "xlsx"])    demo_col1, demo_col2 = st.columns(2)    with demo_col1:        if st.button("Load demo: prepared_samples/nist_prepared.csv"):            demo_path = Path("prepared_samples/nist_prepared.csv")            if demo_path.exists():                up = open(demo_path, "rb")            else:                st.error("Demo file not found. Run the NIST prep step first.")    if up:        df = load_table(up)        st.session_state["last_filename"] = getattr(up, "name", "uploaded_file")        st.caption(f"Loaded: {st.session_state['last_filename']}")        st.session_state.df = df        st.write("Preview:", preview(df))        headers = list(df.columns)        st.markdown("### AI-suggested mapping")        headers = list(df.columns)        # Try LLM mapping first; fall back to fuzzy        llm_suggestion = suggest_mapping_llm(headers, required_metrics + required_meta)        if llm_suggestion and "mapping" in llm_suggestion:            suggested = llm_suggestion["mapping"]            st.caption(f"LLM notes: {llm_suggestion.get('notes','')}")        else:            suggested = suggest_mapping_fuzzy(headers, required_metrics + required_meta)            st.caption("LLM not available → used fuzzy mapping fallback.")        # Let the user override each field        mapping = {}        for m in required_metrics + required_meta:            options = [""] + headers            default_idx = options.index(suggested.get(m, "")) if suggested.get(m, "") in options else 0            mapping[m] = st.selectbox(f"Map '{m}' to column:", options=options, index=default_idx)        st.session_state.mapping = mapping        # === Units for mapped metrics (AI-proposed) ===        st.markdown("### Units for mapped metrics")        proposed_units = propose_units_llm(st.session_state.df, st.session_state.mapping, required_metrics, tpl_units)        units_map = {}        cols = st.columns(min(4, len(required_metrics))) or [st.container()]        for i, m in enumerate(required_metrics):            with cols[i % len(cols)]:                units_map[m] = st.text_input(f"Unit for {m}", value=proposed_units.get(m, ""))        st.session_state.units_map = units_map        st.success("Mapping and units captured. Proceed to Validate tab.")# ---------- Helper: run validation ----------def run_validation(df: pd.DataFrame, mapping: dict, units_map: dict, template: dict) -> pd.DataFrame:    # rename df -> canonical metric names for convenience    rename_map = {v: k for k, v in mapping.items() if v}    working = df.rename(columns=rename_map).copy()    rows = []    for idx, r in working.iterrows():        # build accessible row dict (metric->value)        row_dict = {m: r.get(m, None) for m in set(rename_map.values()) | set(mapping.keys())}        specimen_id = str(r.get("specimen_id", idx))        lot = str(r.get(template.get("grouping", {}).get("lot_id", "lot"), r.get("lot", "")))        statuses = []        rationales = []        for chk in template.get("checks", []):            status, rationale = eval_check(row_dict, chk, units_map)            statuses.append(status)            rationales.append(rationale)        overall = "PASS" if all(s == "PASS" for s in statuses) else ("MISSING" if any(s == "MISSING" for s in statuses) else "FAIL")        rows.append({            "specimen_id": specimen_id,            "lot": lot,            "status": overall,            "rationale": "; ".join(rationales)        })    return pd.DataFrame(rows)# ---------- Tab 2: Validate ----------with tab2:    st.subheader("Run deterministic validation")    if st.session_state.df is None:        st.info("Upload a file in Tab 1.")    else:        if st.button("Validate now"):            res = run_validation(st.session_state.df, st.session_state.mapping, st.session_state.units_map, template)            st.session_state.results_df = res        if st.session_state.results_df is not None:            df = st.session_state.results_df            # KPIs            total = len(df)            n_pass = int((df["status"] == "PASS").sum())            n_fail = int((df["status"] == "FAIL").sum())            n_miss = int((df["status"] == "MISSING").sum())            c1, c2, c3, c4 = st.columns(4)            c1.metric("Specimens", total)            c2.metric("PASS", n_pass)            c3.metric("FAIL", n_fail)            c4.metric("MISSING", n_miss)            # Color style            def _color_status(val):                v = str(val).upper()                if v == "PASS":   return "background-color: #d4edda; color:#155724; font-weight:600;"                if v == "FAIL":   return "background-color: #f8d7da; color:#721c24; font-weight:600;"                if v == "MISSING":return "background-color: #fff3cd; color:#856404; font-weight:600;"                return ""            styled = df.style.map(_color_status, subset=["status"])            st.dataframe(styled, use_container_width=True)            st.success("Validation complete. Open the Explanations tab.")# ---------- Tab 3: Explanations ----------with tab3:    st.subheader("Generate grounded LLM explanations")    if st.session_state.results_df is None:        st.info("Run validation first.")    else:        df = st.session_state.results_df        # choose a specimen (default to first FAIL if any)        default_index = df.index[df["status"] == "FAIL"].tolist()        default_index = default_index[0] if default_index else 0        choice = st.selectbox("Pick specimen", options=list(df["specimen_id"]), index=default_index)        row = df[df["specimen_id"] == choice].iloc[0]        if df["status"].eq("FAIL").sum() == 0:            st.info("All specimens passed. You can still generate an explanation for any specimen.")                # Build a compact checks table from the row's rationale (already includes metrics & margins)        checks_table = row["rationale"].replace("; ", "\n")        if st.button("Explain selected specimen"):            text = explain_specimen(std_id, std_ver, row["specimen_id"], row.get("lot", ""), checks_table)            # Enrich with domain playbook tips            text = enrich_with_playbook(row, text)            st.session_state.explanations[row["specimen_id"]] = text            st.markdown(f"**Explanation for {row['specimen_id']}:**\n\n{text}")        if st.session_state.explanations:            st.markdown("### Saved explanations")            for sid, txt in list(st.session_state.explanations.items()):                row_i = st.session_state.results_df[st.session_state.results_df["specimen_id"] == sid]                if not row_i.empty:                    txt = enrich_with_playbook(row_i.iloc[0], txt)                    st.session_state.explanations[sid] = txt                st.markdown(f"- **{sid}**: {txt}")# ---------- Tab 4: Export ----------with tab4:    st.subheader("Export a 1-page PDF report")    if st.session_state.results_df is None:        st.info("Run validation first.")    else:        outname = st.text_input("Output filename", value="ComplianceReport.pdf")        if st.button("Generate PDF"):            path = make_pdf(st.session_state.results_df, {"standard_id": std_id, "version": std_ver}, st.session_state.explanations, out_path=outname)            if Path(path).exists():                with open(path, "rb") as f:                    st.download_button("Download PDF", data=f, file_name=outname, mime="application/pdf")                st.success(f"Generated {outname}")            else:                st.error("PDF generation failed.")